using System.Collections.Generic;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using EcsGenerator;

[Generator]
public class EcsSourceGenerator : IIncrementalGenerator
{
    private const string AttributeSourceCode = """
        // <auto-generated/>
        using System;

        namespace Common.EcsV2
        {
            [AttributeUsage(AttributeTargets.Struct)]
            public class GenerateEcsComponentAttribute : Attribute
            {
                public EcsComponentFlags Flags { get; }

                public GenerateEcsComponentAttribute(EcsComponentFlags flags)
                {
                    Flags = flags;
                }
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // Add the marker attribute to the compilation
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource(
            "GenerateEcsComponentAttribute.g.cs",
            SourceText.From(AttributeSourceCode, Encoding.UTF8)));

        // Filter structs annotated with the [GenerateEcsComponent] attribute
        var provider = context.SyntaxProvider
            .CreateSyntaxProvider(
                (s, _) => s is StructDeclarationSyntax,
                (ctx, _) => GetComponentDeclarationForSourceGen(ctx))
            .Where(t => t.componentInfo != null || !t.diagnostics.IsEmpty);

        // Generate the source code and report diagnostics
        context.RegisterSourceOutput(provider.Collect(),
            (ctx, results) => GenerateEcsWorld(ctx, results));
    }

    private static (ComponentInfo? componentInfo, ImmutableArray<Diagnostic> diagnostics) GetComponentDeclarationForSourceGen(
        GeneratorSyntaxContext context)
    {
        var structSyntax = (StructDeclarationSyntax)context.Node;

        // Go through all attributes of the struct
        foreach (var attributeList in structSyntax.AttributeLists)
        foreach (var attribute in attributeList.Attributes)
        {
            if (context.SemanticModel.GetSymbolInfo(attribute).Symbol is not IMethodSymbol attributeSymbol)
                continue;

            string attributeName = attributeSymbol.ContainingType.ToDisplayString();

            // Check for [GenerateEcsComponent] attribute
            if (attributeName == "Common.EcsV2.GenerateEcsComponentAttribute")
            {
                var structSymbol = context.SemanticModel.GetDeclaredSymbol(structSyntax) as INamedTypeSymbol;
                if (structSymbol == null)
                    continue;

                // Validate the component and collect diagnostics
                var validationResult = ValidateComponent(structSymbol, structSyntax);
                
                if (!validationResult.isValid)
                {
                    // Return diagnostics without component info for invalid components
                    return (null, validationResult.diagnostics);
                }

                var flags = GetComponentFlags(structSymbol);
                var componentInfo = new ComponentInfo(
                    structSymbol.Name,
                    structSymbol.ContainingNamespace.ToDisplayString(),
                    flags
                );

                return (componentInfo, validationResult.diagnostics);
            }
        }

        return (null, ImmutableArray<Diagnostic>.Empty);
    }

    private static (bool isValid, ImmutableArray<Diagnostic> diagnostics) ValidateComponent(
        INamedTypeSymbol structSymbol, 
        StructDeclarationSyntax structSyntax)
    {
        var diagnostics = ImmutableArray.CreateBuilder<Diagnostic>();
        bool isValid = true;

        // Check if it's actually a struct
        if (structSymbol.TypeKind != TypeKind.Struct)
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.MustBeStructRule,
                structSyntax.GetLocation(),
                structSymbol.Name);
            diagnostics.Add(diagnostic);
            isValid = false;
        }

        // Check if it's partial
        if (!structSyntax.Modifiers.Any(m => m.IsKind(SyntaxKind.PartialKeyword)))
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.MustBePartialRule,
                structSyntax.GetLocation(),
                structSymbol.Name);
            diagnostics.Add(diagnostic);
            isValid = false;
        }

        // Check if it implements IComponent
        var implementsIComponent = structSymbol.AllInterfaces.Any(i => 
            i.Name == "IComponent" && i.ContainingNamespace.ToDisplayString() == "Common.EcsV2");
        
        if (!implementsIComponent)
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.MustImplementIComponentRule,
                structSyntax.GetLocation(),
                structSymbol.Name);
            diagnostics.Add(diagnostic);
            isValid = false;
        }

        // Validate component flags
        var flags = GetComponentFlags(structSymbol);
        var flagValidation = ValidateComponentFlags(structSymbol.Name, flags, structSyntax.GetLocation());
        diagnostics.AddRange(flagValidation.diagnostics);
        if (!flagValidation.isValid)
            isValid = false;

        return (isValid, diagnostics.ToImmutable());
    }

    private static (bool isValid, ImmutableArray<Diagnostic> diagnostics) ValidateComponentFlags(
        string componentName, 
        ComponentFlags flags, 
        Location location)
    {
        var diagnostics = ImmutableArray.CreateBuilder<Diagnostic>();
        bool isValid = true;

        // Check for conflicting storage flags
        bool hasDense = flags.HasFlag(ComponentFlags.Dense);
        bool hasSparse = flags.HasFlag(ComponentFlags.Sparse);

        if (hasDense && hasSparse)
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.ConflictingFlagsRule,
                location,
                componentName);
            diagnostics.Add(diagnostic);
            isValid = false;
        }

        // Check if no storage flags are specified
        if (!hasDense && !hasSparse)
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.NoStorageFlagsRule,
                location,
                componentName);
            diagnostics.Add(diagnostic);
            isValid = false;
        }

        // Check for conflicting sync flags
        var syncFlags = new[]
        {
            (ComponentFlags.ReliableSync, "ReliableSync"),
            (ComponentFlags.UnreliableSync, "UnreliableSync"),
            (ComponentFlags.NoSync, "NoSync"),
            (ComponentFlags.SyncOnce, "SyncOnce")
        };

        var activeSyncFlags = syncFlags.Where(sf => flags.HasFlag(sf.Item1)).ToList();
        
        if (activeSyncFlags.Count > 1)
        {
            var conflictingFlags = string.Join(", ", activeSyncFlags.Select(sf => sf.Item2));
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.ConflictingSyncFlagsRule,
                location,
                componentName,
                conflictingFlags);
            diagnostics.Add(diagnostic);
            // This is a warning, not an error, so don't set isValid = false
        }

        // Check for invalid combinations
        if (flags.HasFlag(ComponentFlags.ImmediateSync) && flags.HasFlag(ComponentFlags.NoSync))
        {
            var diagnostic = Diagnostic.Create(
                EcsGeneratorRules.InvalidFlagCombinationRule,
                location,
                componentName,
                "ImmediateSync cannot be used with NoSync");
            diagnostics.Add(diagnostic);
            // This is a warning, not an error
        }

        return (isValid, diagnostics.ToImmutable());
    }

    private static ComponentFlags GetComponentFlags(INamedTypeSymbol structSymbol)
    {
        var attribute = structSymbol.GetAttributes()
            .FirstOrDefault(a => a.AttributeClass?.Name == "GenerateEcsComponentAttribute");

        if (attribute == null || attribute.ConstructorArguments.Length == 0)
            return ComponentFlags.None;

        var flagsValue = (int)attribute.ConstructorArguments[0].Value!;
        return (ComponentFlags)flagsValue;
    }

    private static void GenerateEcsWorld(SourceProductionContext context, ImmutableArray<(ComponentInfo? componentInfo, ImmutableArray<Diagnostic> diagnostics)> results)
    {
        // Report all diagnostics first
        foreach (var result in results)
        {
            foreach (var diagnostic in result.diagnostics)
            {
                context.ReportDiagnostic(diagnostic);
            }
        }

        // Collect valid components
        var components = results
            .Where(r => r.componentInfo != null)
            .Select(r => r.componentInfo!)
            .ToImmutableArray();

        if (components.IsEmpty)
            return;

        var sourceCode = BuildEcsWorldClass(components);
        context.AddSource("EcsWorld.g.cs", SourceText.From(sourceCode, Encoding.UTF8));
    }

    private static string BuildEcsWorldClass(ImmutableArray<ComponentInfo> components)
    {
        var sb = new StringBuilder();
        
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("using System;");
        sb.AppendLine("using System.Collections;");
        sb.AppendLine("using System.Collections.Generic;");
        sb.AppendLine("using System.Linq;");
        sb.AppendLine("using Common.EcsV2;");
        sb.AppendLine();
        sb.AppendLine("namespace Common.EcsV2;");
        sb.AppendLine();
        sb.AppendLine("public partial class EcsWorld");
        sb.AppendLine("{");
        
        // Entity management
        GenerateEntityManagement(sb);
        
        // Component storage and methods for each component
        foreach (var component in components)
        {
            GenerateComponentStorage(sb, component);
            GenerateComponentMethods(sb, component);
        }
        
        // Universal methods
        GenerateUniversalMethods(sb, components);
        
        // Query methods
        GenerateQueryMethods(sb, components);
        
        // DeleteEntity implementation
        GenerateDeleteEntityImplementation(sb, components);
        
        sb.AppendLine("}");
        
        return sb.ToString();
    }

    private static void GenerateEntityManagement(StringBuilder sb)
    {
        sb.AppendLine("    // Entity ID management");
        sb.AppendLine("    private int _nextEntityId = 1;");
        sb.AppendLine("    private readonly Stack<int> _freeEntityIds = new();");
        sb.AppendLine();
        sb.AppendLine("    public EntityId CreateEntity()");
        sb.AppendLine("    {");
        sb.AppendLine("        return _freeEntityIds.Count > 0");
        sb.AppendLine("            ? new EntityId(_freeEntityIds.Pop())");
        sb.AppendLine("            : new EntityId(_nextEntityId++);");
        sb.AppendLine("    }");
        sb.AppendLine();
    }

    private static void GenerateDeleteEntityImplementation(StringBuilder sb, ImmutableArray<ComponentInfo> components)
    {
        sb.AppendLine("    public void DeleteEntity(EntityId id)");
        sb.AppendLine("    {");
        sb.AppendLine("        _freeEntityIds.Push(id.Value);");
        sb.AppendLine("        // Remove from all components");
        
        foreach (var component in components)
        {
            sb.AppendLine($"        Remove{component.Name}(id);");
        }
        
        sb.AppendLine("    }");
        sb.AppendLine();
    }

    private static void GenerateComponentStorage(StringBuilder sb, ComponentInfo component)
    {
        sb.AppendLine($"    // Storage for {component.Name}");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"    private {component.Name}[] _data_{component.Name} = new {component.Name}[1024];");
            sb.AppendLine($"    private BitArray _set_{component.Name} = new(1024);");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"    private BitArray _dirty_{component.Name} = new(1024);");
            }
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"    private readonly Dictionary<int, {component.Name}> _data_{component.Name} = new();");
            sb.AppendLine($"    private readonly HashSet<int> _set_{component.Name} = new();");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"    private readonly HashSet<int> _dirty_{component.Name} = new();");
            }
        }
        
        sb.AppendLine();
    }

    private static void GenerateComponentMethods(StringBuilder sb, ComponentInfo component)
    {
        var componentName = component.Name;
        
        // Add method
        sb.AppendLine($"    public void Add{componentName}(EntityId id, in {componentName} value)");
        sb.AppendLine("    {");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine("        EnsureCapacity(id.Value);");
            sb.AppendLine($"        _data_{componentName}[id.Value] = value;");
            sb.AppendLine($"        _set_{componentName}[id.Value] = true;");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"        _dirty_{componentName}[id.Value] = true;");
            }
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"        _data_{componentName}[id.Value] = value;");
            sb.AppendLine($"        _set_{componentName}.Add(id.Value);");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"        _dirty_{componentName}.Add(id.Value);");
            }
        }
        
        if (component.Flags.HasFlag(ComponentFlags.ImmediateSync))
        {
            sb.AppendLine("        // TODO: Send immediate sync update");
        }
        
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Remove method
        sb.AppendLine($"    public void Remove{componentName}(EntityId id)");
        sb.AppendLine("    {");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"        if (id.Value < _set_{componentName}.Length)");
            sb.AppendLine("        {");
            sb.AppendLine($"            _set_{componentName}[id.Value] = false;");
            sb.AppendLine($"            _data_{componentName}[id.Value] = default;");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"            _dirty_{componentName}[id.Value] = false;");
            }
            
            sb.AppendLine("        }");
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"        _data_{componentName}.Remove(id.Value);");
            sb.AppendLine($"        _set_{componentName}.Remove(id.Value);");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"        _dirty_{componentName}.Remove(id.Value);");
            }
        }
        
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Has method
        sb.AppendLine($"    public bool Has{componentName}(EntityId id)");
        sb.AppendLine("    {");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"        return id.Value < _set_{componentName}.Length && _set_{componentName}[id.Value];");
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"        return _set_{componentName}.Contains(id.Value);");
        }
        
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Get method (dense only for ref returns)
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"    public ref {componentName} Get{componentName}(EntityId id)");
            sb.AppendLine("    {");
            sb.AppendLine($"        if (!Has{componentName}(id))");
            sb.AppendLine($"            throw new InvalidOperationException($\"Entity {{id}} does not have {componentName} component\");");
            sb.AppendLine($"        return ref _data_{componentName}[id.Value];");
            sb.AppendLine("    }");
            sb.AppendLine();
        }
        
        // TryGet method
        sb.AppendLine($"    public bool TryGet{componentName}(EntityId id, out {componentName} value)");
        sb.AppendLine("    {");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"        if (Has{componentName}(id))");
            sb.AppendLine("        {");
            sb.AppendLine($"            value = _data_{componentName}[id.Value];");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"        return _data_{componentName}.TryGetValue(id.Value, out value);");
        }
        
        sb.AppendLine("        value = default;");
        sb.AppendLine("        return false;");
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // GetEntitiesWith method
        sb.AppendLine($"    public IEnumerable<EntityId> GetEntitiesWith{componentName}()");
        sb.AppendLine("    {");
        
        if (component.Flags.HasFlag(ComponentFlags.Dense))
        {
            sb.AppendLine($"        for (int i = 0; i < _set_{componentName}.Length; i++)");
            sb.AppendLine("        {");
            sb.AppendLine($"            if (_set_{componentName}[i])");
            sb.AppendLine("                yield return new EntityId(i);");
            sb.AppendLine("        }");
        }
        else if (component.Flags.HasFlag(ComponentFlags.Sparse))
        {
            sb.AppendLine($"        return _set_{componentName}.Select(id => new EntityId(id));");
        }
        
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Dirty tracking methods
        if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
        {
            sb.AppendLine($"    public IEnumerable<(EntityId, {componentName})> GetDirty{componentName}()");
            sb.AppendLine("    {");
            
            if (component.Flags.HasFlag(ComponentFlags.Dense))
            {
                sb.AppendLine($"        for (int i = 0; i < _dirty_{componentName}.Length; i++)");
                sb.AppendLine("        {");
                sb.AppendLine($"            if (_dirty_{componentName}[i] && _set_{componentName}[i])");
                sb.AppendLine($"                yield return (new EntityId(i), _data_{componentName}[i]);");
                sb.AppendLine("        }");
            }
            else if (component.Flags.HasFlag(ComponentFlags.Sparse))
            {
                sb.AppendLine($"        foreach (var id in _dirty_{componentName})");
                sb.AppendLine("        {");
                sb.AppendLine($"            if (_data_{componentName}.TryGetValue(id, out var value))");
                sb.AppendLine("                yield return (new EntityId(id), value);");
                sb.AppendLine("        }");
            }
            
            sb.AppendLine("    }");
            sb.AppendLine();
            
            sb.AppendLine($"    public void Clear{componentName}Dirty(EntityId id)");
            sb.AppendLine("    {");
            
            if (component.Flags.HasFlag(ComponentFlags.Dense))
            {
                sb.AppendLine($"        if (id.Value < _dirty_{componentName}.Length)");
                sb.AppendLine($"            _dirty_{componentName}[id.Value] = false;");
            }
            else if (component.Flags.HasFlag(ComponentFlags.Sparse))
            {
                sb.AppendLine($"        _dirty_{componentName}.Remove(id.Value);");
            }
            
            sb.AppendLine("    }");
            sb.AppendLine();
            
            sb.AppendLine($"    public void ClearAll{componentName}Dirty()");
            sb.AppendLine("    {");
            
            if (component.Flags.HasFlag(ComponentFlags.Dense))
            {
                sb.AppendLine($"        _dirty_{componentName}.SetAll(false);");
            }
            else if (component.Flags.HasFlag(ComponentFlags.Sparse))
            {
                sb.AppendLine($"        _dirty_{componentName}.Clear();");
            }
            
            sb.AppendLine("    }");
            sb.AppendLine();
        }
    }

    private static void GenerateUniversalMethods(StringBuilder sb, ImmutableArray<ComponentInfo> components)
    {
        sb.AppendLine("    // Universal component methods");
        
        // Has<T> method
        sb.AppendLine("    public bool Has<T>(EntityId id) where T : IComponent");
        sb.AppendLine("    {");
        sb.AppendLine("        return typeof(T) switch");
        sb.AppendLine("        {");
        
        foreach (var component in components)
        {
            sb.AppendLine($"            _ when typeof(T) == typeof({component.Name}) => Has{component.Name}(id),");
        }
        
        sb.AppendLine("            _ => throw new NotSupportedException($\"Component type {typeof(T)} is not supported\")");
        sb.AppendLine("        };");
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Remove<T> method
        sb.AppendLine("    public void Remove<T>(EntityId id) where T : IComponent");
        sb.AppendLine("    {");
        sb.AppendLine("        switch (typeof(T))");
        sb.AppendLine("        {");
        
        foreach (var component in components)
        {
            sb.AppendLine($"            case var t when t == typeof({component.Name}):");
            sb.AppendLine($"                Remove{component.Name}(id);");
            sb.AppendLine("                break;");
        }
        
        sb.AppendLine("            default:");
        sb.AppendLine("                throw new NotSupportedException($\"Component type {typeof(T)} is not supported\");");
        sb.AppendLine("        }");
        sb.AppendLine("    }");
        sb.AppendLine();
    }

    private static void GenerateQueryMethods(StringBuilder sb, ImmutableArray<ComponentInfo> components)
    {
        sb.AppendLine("    // Query methods");
        sb.AppendLine("    public IEnumerable<EntityId> GetEntitiesWith<T>() where T : IComponent");
        sb.AppendLine("    {");
        sb.AppendLine("        return typeof(T) switch");
        sb.AppendLine("        {");
        
        foreach (var component in components)
        {
            sb.AppendLine($"            _ when typeof(T) == typeof({component.Name}) => GetEntitiesWith{component.Name}(),");
        }
        
        sb.AppendLine("            _ => throw new NotSupportedException($\"Component type {typeof(T)} is not supported\")");
        sb.AppendLine("        };");
        sb.AppendLine("    }");
        sb.AppendLine();
        
        // Helper method for dense arrays
        sb.AppendLine("    private void EnsureCapacity(int entityId)");
        sb.AppendLine("    {");
        sb.AppendLine("        // Resize arrays if needed for dense components");
        
        foreach (var component in components.Where(c => c.Flags.HasFlag(ComponentFlags.Dense)))
        {
            sb.AppendLine($"        if (entityId >= _data_{component.Name}.Length)");
            sb.AppendLine("        {");
            sb.AppendLine($"            var newSize = Math.Max(entityId + 1, _data_{component.Name}.Length * 2);");
            sb.AppendLine($"            Array.Resize(ref _data_{component.Name}, newSize);");
            sb.AppendLine($"            _set_{component.Name}.Length = newSize;");
            
            if (component.Flags.HasFlag(ComponentFlags.DirtyTracked))
            {
                sb.AppendLine($"            _dirty_{component.Name}.Length = newSize;");
            }
            
            sb.AppendLine("        }");
        }
        
        sb.AppendLine("    }");
    }
}

internal record ComponentInfo(string Name, string Namespace, ComponentFlags Flags);

[System.Flags]
internal enum ComponentFlags
{
    None = 0,
    Dense = 1 << 0,
    Sparse = 1 << 1,
    DirtyTracked = 1 << 2,
    ImmediateSync = 1 << 3,
    ReliableSync = 1 << 4,
    UnreliableSync = 1 << 5,
    NoSync = 1 << 6,
    SyncOnce = 1 << 7
}
